function normalizeErrorMessage(message: unknown): string {
  return String(message || "").toLowerCase();
}

export function getErrorInfo(statusCode: number): ErrorInfo {
  return (
    ERROR_TYPES[statusCode] ||
    (statusCode >= 500
      ? { type: "server_error", code: "internal_server_error" }
      : { type: "invalid_request_error", code: "" })
  );
}

export function getDefaultErrorMessage(statusCode: number): string {
  return DEFAULT_ERROR_MESSAGES[statusCode] || "An error occurred";
}

export function calculateBackoffCooldown(level = 0): number {
  const safeLevel = Math.max(0, Math.floor(level));
  const cooldown = BACKOFF_CONFIG.base * Math.pow(2, safeLevel);
  return Math.min(cooldown, BACKOFF_CONFIG.max);
}

export function matchErrorRuleByText(message: unknown): ErrorRule | null {
  const lower = normalizeErrorMessage(message);
  if (!lower) return null;
  return ERROR_RULES.find((rule) => rule.text && lower.includes(rule.text)) || null;
}

export function matchErrorRuleByStatus(statusCode: number): ErrorRule | null {
  return ERROR_RULES.find((rule) => rule.status === statusCode) || null;
}

export function findMatchingErrorRule(statusCode: number, message: unknown): ErrorRule | null {
  return matchErrorRuleByText(message) || matchErrorRuleByStatus(statusCode);
}

// #8248: NVIDIA NIM function-state DEGRADED — some NIM deployments signal a non-standard
// HTTP 400 whose body reports the backing "function" is DEGRADED (e.g. `Function id "<uuid>"
// submitted for inference is DEGRADED`) instead of a clean model-not-found/5xx. Bounded
// lookahead ({0,80}) — ReDoS-safe, no nested quantifiers.
const NIM_FUNCTION_DEGRADED_PATTERNS = [
  /\bfunction\b[\s\S]{0,80}?\bDEGRADED\b/i,
  /\bDEGRADED\b[\s\S]{0,80}?\bfunction\b/i,
];

export function isNimFunctionDegraded(errorText: string): boolean {
  return NIM_FUNCTION_DEGRADED_PATTERNS.some((p) => p.test(errorText));
}

export interface ServiceSupervisorCooldown {
  shouldFallback: true;
  cooldownMs: number;
  baseCooldownMs: number;
  newBackoffLevel: 0;
  reason: string;
  skipProviderBreaker: true;
}

/**
 * G-02: detect embedded service supervisor failures (X-Omni-Fallback-Hint: connection_cooldown).
 * These are NOT upstream AI provider failures — they are local supervisor state changes. Returns
 * a short 5s connection-cooldown decision (no provider circuit-breaker trip), or null when the
 * status/header don't match.
 */
export function serviceSupervisorCooldown(
  status: number,
  headers: Headers | Record<string, string> | null
): ServiceSupervisorCooldown | null {
  if (status !== 503 || !headers) return null;
  const hintValue =
    typeof (headers as Headers).get === "function"
      ? (headers as Headers).get("x-omni-fallback-hint")
      : (headers as Record<string, string>)["x-omni-fallback-hint"] ||
        (headers as Record<string, string>)["X-Omni-Fallback-Hint"];
  if (typeof hintValue !== "string" || hintValue.toLowerCase() !== "connection_cooldown") {
    return null;
  }
  return {
    shouldFallback: true,
    cooldownMs: 5_000,
    baseCooldownMs: 5_000,
    newBackoffLevel: 0,
    reason: "service_not_running",
    skipProviderBreaker: true,
  };
}

/**
 * Protocolos alternativos declarados por um provedor.
 *
 * Alguns upstreams publicam o mesmo catalogo em mais de um protocolo (ex.: Xiaomi
 * MiMo expoe /v1/chat/completions e /anthropic/v1/messages no mesmo host). Trocar
 * de protocolo troca URL, header de auth e headers extras — por isso a alternativa
 * carrega os tres, nao so a URL.
 *
 * A escolha vive na conexao, em providerSpecificData.targetFormat, e so vale se
 * casar com uma alternativa declarada: valor desconhecido cai no formato padrao,
 * nunca produz uma URL/auth orfas.
 */
import type { RegistryEntry } from "./shared.ts";

export interface AlternateFormat {
  format: string;
  baseUrl: string;
  chatPath?: string;
  authHeader?: string;
  headers?: Record<string, string>;
  urlSuffix?: string;
  label: string;
}

export function resolveAlternateFormat(
  entry: RegistryEntry | null | undefined,
  providerSpecificData: unknown
): AlternateFormat | null {
  const alternates = entry?.alternateFormats;
  if (!alternates?.length) return null;
  const requested = (providerSpecificData as { targetFormat?: unknown } | null | undefined)
    ?.targetFormat;
  if (typeof requested !== "string" || !requested) return null;
  return alternates.find((alt) => alt.format === requested) ?? null;
}

/**
 * Anthropic Context Editing — delegated, server-side compression for Claude.
 *
 * Unlike OmniRoute's local compression engines (which rewrite the request body
 * before it leaves the proxy), Context Editing asks the *provider* to clear
 * stale tool-use/tool-result blocks from the running context window. We only
 * attach a body param (`context_management.edits[]`); Claude does the clearing
 * against its own tokenizer. The beta is advertised via the `anthropic-beta:
 * context-management-2025-06-27` header, which OmniRoute already emits on Claude
 * requests (see `anthropicHeaders.ts`).
 *
 * This is a Claude-only capability by nature — other providers would reject the
 * param. Callers MUST gate invocation to the genuine Claude provider; this
 * module does not inspect the provider itself.
 *
 * Strategy ids and shapes are pinned from live Anthropic docs
 * (platform.claude.com/docs/en/build-with-claude/context-editing).
 */

/** Dated strategy id that clears old tool-use / tool-result pairs. */
export const CLEAR_TOOL_USES_STRATEGY = "clear_tool_uses_20250919";

/** Dated strategy id that clears old extended-thinking turns. */
export const CLEAR_THINKING_STRATEGY = "clear_thinking_20251015";

/** Default token threshold that triggers clearing (Anthropic default is 100k). */
export const CONTEXT_EDITING_DEFAULT_TRIGGER_TOKENS = 100000;

/** Recent tool-use/result pairs kept untouched when clearing. */
export const CONTEXT_EDITING_DEFAULT_KEEP_TOOL_USES = 3;

type ContextEditingEdit = { type?: unknown; [key: string]: unknown };

/**
 * Mutate an Anthropic Messages request body in place to delegate context
 * clearing to the provider. Adds the `clear_tool_uses_20250919` strategy to
 * `context_management.edits[]`, composing with any `clear_thinking_20251015`
 * edit already present — Anthropic requires `clear_thinking` to be listed first,
 * so thinking edits are stable-sorted to the front.
 *
 * Idempotent: if a `clear_tool_uses` edit already exists (added by a previous
 * call or supplied by the client), the body is left as-is. No-op when disabled
 * or when `body` is not a plain object.
 *
 * @param body  The outbound Anthropic-format request body (mutated in place).
 * @param opts.enabled  Whether Context Editing is on for this request.
 */
export function applyContextEditingToBody(
  body: Record<string, unknown> | null | undefined,
  opts: { enabled: boolean }
): void {
  if (!opts.enabled || !body || typeof body !== "object") return;

  const existing =
    body.context_management && typeof body.context_management === "object"
      ? (body.context_management as Record<string, unknown>)
      : {};

  const edits: ContextEditingEdit[] = Array.isArray(existing.edits)
    ? [...(existing.edits as ContextEditingEdit[])]
    : [];

  const hasToolUseEdit = edits.some((edit) => edit && edit.type === CLEAR_TOOL_USES_STRATEGY);

  if (!hasToolUseEdit) {
    edits.push({
      type: CLEAR_TOOL_USES_STRATEGY,
      trigger: { type: "input_tokens", value: CONTEXT_EDITING_DEFAULT_TRIGGER_TOKENS },
      keep: { type: "tool_uses", value: CONTEXT_EDITING_DEFAULT_KEEP_TOOL_USES },
    });
    // Anthropic requires clear_thinking edits to precede clear_tool_uses. Array
    // sort is stable in modern Node, so same-key edits keep their relative order.
    edits.sort((a, b) => {
      const aRank = a && a.type === CLEAR_THINKING_STRATEGY ? 0 : 1;
      const bRank = b && b.type === CLEAR_THINKING_STRATEGY ? 0 : 1;
      return aRank - bRank;
    });
  }

  existing.edits = edits;
  body.context_management = existing;
}

/**
 * Telemetry receipt for one Claude response that ran server-side context editing.
 * `clearedInputTokens` is how many input tokens the provider pruned from its own
 * context window — i.e. the tokens "saved" on subsequent turns by the delegated
 * clearing (the value we surface in compression analytics under
 * `engine: "context-editing"`).
 */
export interface ContextEditingTelemetry {
  /** Number of applied edit entries the provider reported. */
  editCount: number;
  /** Total input tokens cleared across all applied edits. */
  clearedInputTokens: number;
  /** Total tool-use/result pairs cleared across all applied edits. */
  clearedToolUses: number;
}

/** Coerce a finite, non-negative integer; returns 0 for junk. */
function toClearedInt(value: unknown): number {
  if (typeof value === "number" && Number.isFinite(value)) return Math.max(0, Math.floor(value));
  if (typeof value === "string" && value.trim()) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) return Math.max(0, Math.floor(parsed));
  }
  return 0;
}

/** Read a nested property by key path without throwing on missing intermediates. */
function getNested(obj: unknown, keys: string[]): unknown {
  let cur: unknown = obj;
  for (const key of keys) {
    if (!cur || typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[key];
  }
  return cur;
}

/**
 * Extract the context-editing telemetry receipt from a Claude (Anthropic Messages)
 * response body. Returns `null` when context editing did not run (no applied edits,
 * or nothing was actually cleared).
 *
 * Defensive over the response shape: Anthropic surfaces `applied_edits` under
 * `context_management` (top-level), and some response variants nest it under
 * `usage`. We probe both rather than pin a single location, so the telemetry keeps
 * working if the provider moves the field. Per-edit cleared counts are read from
 * `cleared_input_tokens` / `cleared_tool_uses` (snake_case) with a camelCase
 * fallback.
 */
export function extractContextEditingTelemetry(
  responseBody: unknown
): ContextEditingTelemetry | null {
  if (!responseBody || typeof responseBody !== "object") return null;

  const candidates: unknown[] = [
    getNested(responseBody, ["context_management", "applied_edits"]),
    getNested(responseBody, ["usage", "context_management", "applied_edits"]),
    getNested(responseBody, ["usage", "applied_edits"]),
  ];
  const edits = candidates.find((c) => Array.isArray(c)) as unknown[] | undefined;
  if (!Array.isArray(edits) || edits.length === 0) return null;

  let clearedInputTokens = 0;
  let clearedToolUses = 0;
  for (const entry of edits) {
    if (!entry || typeof entry !== "object") continue;
    const edit = entry as Record<string, unknown>;
    clearedInputTokens += toClearedInt(edit.cleared_input_tokens ?? edit.clearedInputTokens);
    clearedToolUses += toClearedInt(edit.cleared_tool_uses ?? edit.clearedToolUses);
  }

  if (clearedInputTokens <= 0 && clearedToolUses <= 0) return null;
  return { editCount: edits.length, clearedInputTokens, clearedToolUses };
}

// Fields that, when literally named in an upstream 400 body, are safe to strip and
// retry once (FCC NIM-style recovery). Mirrors the existing context_management 400
// fallback in base.ts, generalized to these OpenAI-compat / NIM reasoning fields.
// `context_management` (9router#1468): Claude Code sends it top-level; strict
// anthropic-compatible gateways 400 with "context_management: Extra inputs are not
// permitted". The dedicated base.ts fallback only fires when OmniRoute's own
// contextEditing feature is enabled, so a client-sent field passed through
// untouched when the feature is off — this generic strip covers that case.
export const KNOWN_OFFENDING_FIELDS: readonly string[] = [
  "reasoning_budget",
  "chat_template",
  "reasoning_content",
  "context_management",
  // GPT-5's Chat Completions-only output control. It can be present when a
  // routing rule substitutes a non-GPT OpenAI-compatible target (for example
  // Codex → GLM or Ollama Cloud), whose strict endpoint rejects it as an extra
  // field. Retrying without it is safe because it only changes output style.
  "verbosity",
];

/** Return the first known-offending field literally named in a 400 body, or null. */
export function findOffendingField(bodyText: string): string | null {
  if (typeof bodyText !== "string" || !bodyText) return null;
  for (const field of KNOWN_OFFENDING_FIELDS) {
    if (bodyText.includes(field)) return field;
  }
  return null;
}

/**
 * Regex to extract an unsupported parameter name from upstream 400 error text.
 * Matches:
 *   - "Unsupported parameter(s): thinking"
 *   - "Unsupported parameter: max_tokens"
 *   - "Unsupported parameter 'reasoning_budget'"
 */
export const UNSUPPORTED_PARAM_RE =
  /unsupported\s+parameter\w*(?:\s*\(s\))?[:\s]+["'`]?(\w+)["'`]?/i;

/**
 * Extract a single unsupported parameter name from a 400 error body,
 * or null if the error does not match the known pattern.
 */
export function detectUnsupportedParam(bodyText: string): string | null {
  if (typeof bodyText !== "string" || !bodyText) return null;
  const match = UNSUPPORTED_PARAM_RE.exec(bodyText);
  return match?.[1] ?? null;
}

/** Immutably drop request fields Groq rejects with a 400. */
export function stripGroqUnsupportedFields<T extends Record<string, unknown>>(body: T): T {
  if (!body || typeof body !== "object") return body;
  const next: Record<string, unknown> = { ...body };
  delete next.logprobs;
  delete next.logit_bias;
  delete next.top_logprobs;
  if (Array.isArray(next.messages)) {
    next.messages = next.messages.map((m) => {
      if (m && typeof m === "object" && "name" in m) {
        const { name: _name, ...rest } = m as Record<string, unknown>;
        return rest;
      }
      return m;
    });
  }
  return next as T;
}

/**
 * Learned Thinking-Budget Caps — reactive cap memory for Gemini-family models.
 *
 * Proactive clamping (`capThinkingBudget` in src/lib/modelCapabilities.ts) only
 * knows caps for models registered in MODEL_SPECS. Any Gemini model outside the
 * registry (e.g. gemini-2.5-pro, or a Gemini id served through another provider)
 * initially gets no cap, so a high client budget (xhigh = 131072) goes straight
 * to the upstream and can bounce with:
 *
 *   400 GenerateContentRequest.generation_config.thinking_config.thinking_budget:
 *   thinking_budget must be in the range [-1, 65535]
 *
 * When base.ts's executor sees that 400 it calls `recordLearnedThinkingCap`,
 * which walks the failed budget down a step ladder and stores the surviving cap
 * in a module-level Map keyed "provider:model" (lowercased). Subsequent requests
 * for the same provider+model read the cap via `getLearnedThinkingCap` (consulted
 * by `capThinkingBudget`) so the 400→retry round-trip is paid at most once per
 * process per provider+model — not once per chat session.
 *
 * In-memory only (per operator decision): restart resets, the first request after
 * a restart may re-learn at the cost of one upstream 400.
 */

// Known Gemini thinking-budget ceilings, highest first. 32768 is the pro-tier
// cap; 24576 is the flash-tier cap (gemini-2.5-flash in MODEL_SPECS); 8192 is a
// conservative floor that every thinking-capable Gemini accepts. A failed budget
// walks to the first step strictly below it.
const GEMINI_STEPDOWN: readonly number[] = [32768, 24576, 8192];

/**
 * Proactive cap applied by `capThinkingBudget` (src/lib/modelCapabilities.ts)
 * when a model id contains "gemini" but has no registry entry and no learned cap.
 * Set to the highest rung of the step ladder so unregistered Gemini models get
 * the maximum reasoning the family is known to accept, rather than letting an
 * xhigh budget (131072) through to a 400.
 */
export const GEMINI_FALLBACK_THINKING_CAP: number = GEMINI_STEPDOWN[0];

// key: `${provider}:${model}` lowercased → highest budget known to be accepted.
const learnedCaps = new Map<string, number>();

function buildKey(provider: string | null | undefined, model: string | null | undefined): string {
  const p = typeof provider === "string" ? provider.trim().toLowerCase() : "";
  const m = typeof model === "string" ? model.trim().toLowerCase() : "";
  if (!p || !m) return "";
  return `${p}:${m}`;
}

/**
 * Return the learned cap for provider+model, or null when nothing has been
 * learned yet (no upstream 400 recorded). Keyed case-insensitively.
 */
export function getLearnedThinkingCap(
  provider: string | null | undefined,
  model: string | null | undefined
): number | null {
  const key = buildKey(provider, model);
  if (!key) return null;
  return learnedCaps.get(key) ?? null;
}

/**
 * Record that `failedBudget` was rejected by the upstream for provider+model and
 * store the next step down as the learned cap. Returns the new cap, or null when
 * the step ladder is exhausted (even 8192 failed) or the key is unusable — the
 * caller should then give up clamping and surface the upstream error.
 *
 * Always monotonically decreases: if a cap already stored is lower than the step
 * we'd compute, the stored (lower) value wins and is returned unchanged. This
 * keeps concurrent failures on the same provider+model from ratcheting the cap
 * back up.
 */
export function recordLearnedThinkingCap(
  provider: string | null | undefined,
  model: string | null | undefined,
  failedBudget: number
): number | null {
  const key = buildKey(provider, model);
  if (!key) return null;
  if (!Number.isFinite(failedBudget)) return null;

  const nextStep = GEMINI_STEPDOWN.find((step) => step < failedBudget);
  if (nextStep === undefined) return null; // ladder exhausted

  const existing = learnedCaps.get(key);
  if (existing !== undefined && existing <= nextStep) {
    return existing; // already learned an equal-or-lower cap; keep it
  }
  learnedCaps.set(key, nextStep);
  return nextStep;
}

/**
 * Extract the upstream-advertised maximum from a thinking_budget range error.
 * Matches both snake_case and camelCase field namings:
 *   "thinking_budget must be in the range [-1, 65535]"   → 65535
 *   "thinkingBudget must be in the range [-1, 24576]"    → 24576
 * Returns null when the text is not a thinking-budget range error.
 */
export function parseThinkingBudgetMax(errText: unknown): number | null {
  if (typeof errText !== "string" || !errText) return null;
  const match = /thinking_?budget[^\d-]*(?:must be in the range|range)[^\d-]*\[\s*-?\d+\s*,\s*(\d+)\s*\]/i.exec(
    errText
  );
  if (!match) return null;
  const max = Number(match[1]);
  return Number.isFinite(max) ? max : null;
}

/** Test-only: clear the learned-cap Map between tests. */
export function __test_resetLearnedThinkingCaps(): void {
  learnedCaps.clear();
}

/**
 * db/paramFilters.ts — Provider/Model parameter filter configuration.
 *
 * CRUD against the key_value table under namespace "provider_param_filters".
 * Follows the established key_value pattern from databaseSettings.ts.
 */

import { getDbInstance } from "./core";

const NAMESPACE = "provider_param_filters";

// ── Types ───────────────────────────────────────────────────────────────────

export interface ModelParamFilter {
  block?: string[];
  allow?: string[];
}

export interface ProviderParamFilter {
  /** Provider-level params to strip from all requests to this provider. */
  block: string[];
  /** Provider-level params to re-add after denylist stripping. */
  allow: string[];
  /** Model-specific overrides (stricter than provider-level). */
  models?: Record<string, ModelParamFilter>;
  /** When true, upstream 400 "Unsupported parameter" errors auto-populate block. */
  autoLearn?: boolean;
}

// ── Cache ───────────────────────────────────────────────────────────────────

let filterCache: Map<string, ProviderParamFilter> | null = null;
let cacheGeneration = 0;

function bumpCacheGeneration(): void {
  cacheGeneration++;
  filterCache = null;
}

// ── Helpers ─────────────────────────────────────────────────────────────────

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function parseStoredValue(raw: unknown): unknown {
  if (typeof raw !== "string") return raw;
  try {
    return JSON.parse(raw);
  } catch {
    return raw;
  }
}

function toNormalizedString(value: unknown): string | null {
  return typeof value === "string" && value.length > 0 ? value : null;
}

function toStringArray(value: unknown): string[] {
  return Array.isArray(value) ? value.filter((k): k is string => typeof k === "string") : [];
}

function toModelParamFilter(raw: Record<string, unknown>): ModelParamFilter | null {
  const block = toStringArray(raw.block);
  const allow = toStringArray(raw.allow);
  if (block.length === 0 && allow.length === 0) return null;
  const filter: ModelParamFilter = {};
  if (block.length > 0) filter.block = block;
  if (allow.length > 0) filter.allow = allow;
  return filter;
}

function toModelParamFilters(raw: unknown): Record<string, ModelParamFilter> {
  const models: Record<string, ModelParamFilter> = {};
  if (!isRecord(raw)) return models;
  for (const [modelId, val] of Object.entries(raw)) {
    if (!isRecord(val)) continue;
    const filter = toModelParamFilter(val);
    if (filter) models[modelId] = filter;
  }
  return models;
}

function toProviderParamFilter(raw: unknown): ProviderParamFilter | null {
  if (!isRecord(raw)) return null;
  const block = toStringArray(raw.block);
  const allow = toStringArray(raw.allow);
  const models = toModelParamFilters(raw.models);
  const autoLearn = typeof raw.autoLearn === "boolean" ? raw.autoLearn : false;
  return { block, allow, models: Object.keys(models).length > 0 ? models : undefined, autoLearn };
}

// ── Read ────────────────────────────────────────────────────────────────────

function readNamespace(namespace: string): Record<string, unknown> {
  const db = getDbInstance();
  const rows = db
    .prepare("SELECT key, value FROM key_value WHERE namespace = ?")
    .all(namespace) as Array<{ key: string; value: string }>;

  const values: Record<string, unknown> = {};
  for (const row of rows) {
    values[row.key] = parseStoredValue(row.value);
  }
  return values;
}

function loadAllConfigs(): Map<string, ProviderParamFilter> {
  const raw = readNamespace(NAMESPACE);
  const map = new Map<string, ProviderParamFilter>();
  for (const [key, value] of Object.entries(raw)) {
    const parsed = toProviderParamFilter(value);
    if (parsed) {
      map.set(key, parsed);
    }
  }
  return map;
}

// ── Public API ──────────────────────────────────────────────────────────────

/**
 * Warm the cache on module load so the first call to getParamFilterConfig
 * does not hit the DB. Idempotent — subsequent calls return the cached map.
 */
export function loadParamFilterConfigs(): Map<string, ProviderParamFilter> {
  if (filterCache === null) {
    filterCache = loadAllConfigs();
  }
  return filterCache;
}

/**
 * Get the param filter config for a single provider, or null if not configured.
 * Uses an in-memory cache refreshed on write.
 */
export function getParamFilterConfig(provider: string): ProviderParamFilter | null {
  return toNormalizedString(provider) ? (loadParamFilterConfigs().get(provider) ?? null) : null;
}

/**
 * Upsert the entire param filter config for a provider.
 * Invalidates the in-memory cache.
 */
export function setParamFilterConfig(provider: string, config: ProviderParamFilter): void {
  if (!toNormalizedString(provider)) return;

  const db = getDbInstance();
  const stmt = db.prepare(
    "INSERT OR REPLACE INTO key_value (namespace, key, value) VALUES (?, ?, ?)"
  );

  // Normalize the filter before persisting
  const normalized: ProviderParamFilter = {
    block: config.block ?? [],
    allow: config.allow ?? [],
    autoLearn: config.autoLearn ?? false,
    models: config.models && Object.keys(config.models).length > 0 ? config.models : undefined,
  };

  stmt.run(NAMESPACE, provider, JSON.stringify(normalized));
  bumpCacheGeneration();
}

/**
 * Delete the param filter config for a provider.
 * Resets to no filtering for that provider.
 */
export function deleteParamFilterConfig(provider: string): void {
  if (!toNormalizedString(provider)) return;

  const db = getDbInstance();
  const stmt = db.prepare("DELETE FROM key_value WHERE namespace = ? AND key = ?");
  stmt.run(NAMESPACE, provider);
  bumpCacheGeneration();
}

// ── Global auto-learn flag ──────────────────────────────────────────────────

const GLOBAL_AUTOLEARN_KEY = "__global__";

/**
 * Check whether the global auto-learn flag is enabled.
 * When enabled, ALL providers auto-learn unsupported params from 400 errors
 * regardless of their per-provider autoLearn setting.
 * Only fires when this is explicitly configured, else returns false.
 */
export function isAutoLearnGloballyEnabled(): boolean {
  const globalCfg = getParamFilterConfig(GLOBAL_AUTOLEARN_KEY);
  return globalCfg?.autoLearn === true;
}

/**
 * Enable or disable global auto-learn globally for all providers.
 * When enabled, the per-provider autoLearn flag is still honored after
 * the global check (either being on is sufficient to trigger auto-learn).
 */
export function setGlobalAutoLearnEnabled(enabled: boolean): void {
  const existing = getParamFilterConfig(GLOBAL_AUTOLEARN_KEY);
  setParamFilterConfig(GLOBAL_AUTOLEARN_KEY, {
    block: existing?.block ?? [],
    allow: existing?.allow ?? [],
    autoLearn: enabled,
  });
}

/**
 * Auto-learn helper: add a single parameter to a provider's block list.
 * If the field is already in the block list (or the config does not exist),
 * this is a no-op. Optionally scoped to a specific model.
 */
export function addParamToBlocklist(provider: string, paramName: string, model?: string): void {
  if (!toNormalizedString(provider) || !toNormalizedString(paramName)) return;

  const existing = getParamFilterConfig(provider) ?? {
    block: [],
    allow: [],
    autoLearn: false,
  };

  if (model) {
    // Model-level
    const models = existing.models ?? {};
    const modelCfg = models[model] ?? {};

    if (Array.isArray(modelCfg.block) && modelCfg.block.includes(paramName)) return;

    const updatedBlock = [...(modelCfg.block ?? []), paramName];
    models[model] = { ...modelCfg, block: updatedBlock };
    existing.models = models;
  } else {
    // Provider-level
    if (existing.block.includes(paramName)) return;
    existing.block = [...existing.block, paramName];
  }

  setParamFilterConfig(provider, existing);
}

