  category: "compatible";
  displayAuthType: "compatible";
  toggleAuthType: "apikey";
  isCompatible: true;
  type?: string | null;
}

export type ResolvedProviderCatalogEntry =
  | ResolvedStaticProviderCatalogEntry
  | ResolvedCompatibleProviderCatalogEntry;

