const EMBEDDING_PROVIDER_ALIASES: Record<string, string> = {
  jina: "jina-ai",
  voyage: "voyage-ai",
};

function resolveEmbeddingProviderId(providerId: string): string {
  return EMBEDDING_PROVIDER_ALIASES[providerId] || providerId;
}

function normalizeProviderScopedModelId(providerId: string, modelId: string): string {
  const resolvedProvider = resolveEmbeddingProviderId(providerId);
  const provider = EMBEDDING_PROVIDERS[resolvedProvider];
  if (provider?.models.some((model) => model.id === modelId)) return modelId;

  const providerScopedModelId = `${resolvedProvider}/${modelId}`;
  if (provider?.models.some((model) => model.id === providerScopedModelId)) {
    return providerScopedModelId;
  }

  return modelId.startsWith(`${providerId}/`) ? modelId.slice(providerId.length + 1) : modelId;
}

function toProviderScopedModelId(providerId: string, modelId: string): string {
  return modelId.startsWith(`${providerId}/`) ? modelId : `${providerId}/${modelId}`;
}

/**
 * Get embedding provider config by ID
 */
export function getEmbeddingProvider(providerId: string): EmbeddingProvider | null {
  return EMBEDDING_PROVIDERS[resolveEmbeddingProviderId(providerId)] || null;
}

/**
 * Parse embedding model string (format: "provider/model" or just "model")
 * Returns { provider, model }
 */
export function parseEmbeddingModel(
  modelStr: string | null,
  dynamicProviders?: EmbeddingProvider[]
): { provider: string | null; model: string | null } {
  if (!modelStr) return { provider: null, model: null };

  // Check for "provider/model" format
  const slashIdx = modelStr.indexOf("/");
  if (slashIdx > 0) {
    const rawProvider = modelStr.slice(0, slashIdx);
    const resolvedProvider = resolveEmbeddingProviderId(rawProvider);

    if (EMBEDDING_PROVIDERS[resolvedProvider]) {
      return {
        provider: resolvedProvider,
        model: normalizeProviderScopedModelId(resolvedProvider, modelStr.slice(slashIdx + 1)),
      };
    }

    // Phase 1: Try each hardcoded provider prefix
    for (const [providerId] of Object.entries(EMBEDDING_PROVIDERS)) {
      if (modelStr.startsWith(providerId + "/")) {
        return {
          provider: providerId,
          model: normalizeProviderScopedModelId(providerId, modelStr.slice(providerId.length + 1)),
        };
      }
    }
    // Phase 2: Try dynamic provider_nodes prefix
    if (dynamicProviders) {
      for (const dp of dynamicProviders) {
        if (modelStr.startsWith(dp.id + "/")) {
          return { provider: dp.id, model: modelStr.slice(dp.id.length + 1) };
        }
      }
    }
    // Phase 3: Fallback — first segment is provider
    const provider = modelStr.slice(0, slashIdx);
    const model = modelStr.slice(slashIdx + 1);
    return { provider, model };
  }

  // No provider prefix — search hardcoded providers for the model
  for (const [providerId, config] of Object.entries(EMBEDDING_PROVIDERS)) {
    if (config.models.some((m) => m.id === modelStr)) {
      return { provider: providerId, model: modelStr };
    }
  }

  return { provider: null, model: modelStr };
}

/**
 * Resolve the known vector dimension of an embedding model string
 * (format: "provider/model"). Returns undefined when the provider/model is
 * unknown or the registry has no dimension recorded for it (e.g. local/custom
 * providers) — callers treat undefined as "can't assert", not "zero".
 */
export function getEmbeddingDimension(modelStr: string): number | undefined {
  const { provider, model } = parseEmbeddingModel(modelStr);
  if (!provider || !model) return undefined;
  const config = getEmbeddingProvider(provider);
  if (!config) return undefined;
  return config.models.find((m) => m.id === model)?.dimensions;
}

/**
 * Detect whether a set of embedding model strings spans more than one known
 * vector dimension. Vectors from models of different dimensions live in
 * incompatible spaces, so failing over between them silently corrupts any
 * vector store built on top of the proxy. Models with an *unknown* dimension
 * are ignored (conservative: we never flag a conflict we can't prove).
 */
export function detectEmbeddingDimensionConflict(modelStrs: string[]): {
  conflict: boolean;
  dimensions: Record<string, number>;
  distinct: number[];
} {
  const dimensions: Record<string, number> = {};
  for (const modelStr of modelStrs) {
    const dim = getEmbeddingDimension(modelStr);
    if (typeof dim === "number") dimensions[modelStr] = dim;
  }
  const distinct = [...new Set(Object.values(dimensions))].sort((a, b) => a - b);
  return { conflict: distinct.length > 1, dimensions, distinct };
}

/**
 * Resolve the model-level default request params for a given provider config and
 * model id. Returns undefined when the model has no defaults (the common case),
 * so callers only inject for models that actually carry one (e.g. NVIDIA NIM
 * asymmetric embedders requiring `input_type`). See issue #1378.
 */
export function getEmbeddingModelDefaultParams(
  providerConfig: EmbeddingProvider | null,
  modelId: string | null
): Record<string, unknown> | undefined {
  if (!providerConfig || !modelId) return undefined;
  return providerConfig.models.find((m) => m.id === modelId)?.defaultParams;
}

export function getEmbeddingModelModalities(
  providerConfig: EmbeddingProvider | null,
  modelId: string | null
): EmbeddingModality[] | undefined {
  if (!providerConfig || !modelId) return undefined;
  return providerConfig.models.find((model) => model.id === modelId)?.modalities;
}

/**
 * Get all embedding models as a flat list
 */
export function getAllEmbeddingModels() {
  const models: Array<{
    id: string;
    name: string;
    provider: string;
    dimensions: number | undefined;
  }> = [];
  for (const [providerId, config] of Object.entries(EMBEDDING_PROVIDERS)) {
    for (const model of config.models) {
      models.push({
        id: toProviderScopedModelId(providerId, model.id),
        name: model.name,
        provider: providerId,
        dimensions: model.dimensions,
      });
    }
  }
  return models;
}

/**
 * OCR Provider Registry
 *
 * Defines providers that support the /v1/ocr endpoint.
 * Follows Mistral's OCR API format.
 */

export interface OcrModel {
  id: string;
  name: string;
}

export interface OcrProvider {
  id: string;
  baseUrl: string;
  authType: string;
  authHeader: string;
  models: OcrModel[];
}

export interface ParsedOcrModel {
  provider: string | null;
  model: string | null;
}

export const OCR_PROVIDERS: Record<string, OcrProvider> = {
  mistral: {
    id: "mistral",
    baseUrl: "https://api.mistral.ai/v1/ocr",
    authType: "apikey",
    authHeader: "bearer",
    models: [{ id: "mistral-ocr-latest", name: "Mistral OCR" }],
  },
};

/**
 * Get OCR provider config by ID.
 */
export function getOcrProvider(providerId: string): OcrProvider | null {
  return OCR_PROVIDERS[providerId] || null;
}

/**
 * Parse an OCR model string.
 *
 * Accepts either a "provider/model" prefixed string or a bare model id that
 * matches one of the registered OCR models.
 */
export function parseOcrModel(modelStr: string | null | undefined): ParsedOcrModel {
  if (!modelStr) return { provider: null, model: null };

  for (const providerId of Object.keys(OCR_PROVIDERS)) {
    if (modelStr.startsWith(providerId + "/")) {
      return { provider: providerId, model: modelStr.slice(providerId.length + 1) };
    }
  }

  for (const [providerId, config] of Object.entries(OCR_PROVIDERS)) {
    if (config.models.some((m) => m.id === modelStr)) {
      return { provider: providerId, model: modelStr };
    }
  }

  return { provider: null, model: modelStr };
}

/**
 * Get all OCR models as a flat list.
 */
export function getAllOcrModels(): Array<{ id: string; name: string; provider: string }> {
  const models: Array<{ id: string; name: string; provider: string }> = [];
  for (const [providerId, config] of Object.entries(OCR_PROVIDERS)) {
    for (const model of config.models) {
      models.push({
        id: `${providerId}/${model.id}`,
        name: model.name,
        provider: providerId,
      });
    }
  }
  return models;
}

/**
 * Türkçe-güvenli metin normalizasyonu, arama ve sıralama yardımcıları.
 *
 * JavaScript'in locale-bağımsız `toLowerCase()`'i Türkçe `İ/I/ı/i`
 * karakterlerini bozar: `"İ".toLowerCase()` → `"i̇"` (U+0069 U+0307
 * combining dot above). Bu, `toLowerCase().includes()` tabanlı aramada
 * Türkçe girdileri eşleşmez kılar.
 *
 * Saf fonksiyonlar — yan etki ve bağımlılık yok.
 *
 * @module shared/utils/turkishText
 */

/** NFD ile katlanmayan Türkçe harfler için açık eşleme. */
const TR_FOLD: Readonly<Record<string, string>> = {
  ı: "i",
  ş: "s",
  ğ: "g",
  ü: "u",
  ö: "o",
  ç: "c",
};

/**
 * Aksan-duyarsız, Türkçe-güvenli arama anahtarı üretir.
 * `"İstanbul"` ve `"istanbul"` → `"istanbul"`; `"Şarj"` → `"sarj"`.
 * Baştaki ve sondaki boşluklar kırpılır.
 */
export function normalizeForSearch(input: string | null | undefined): string {
  if (!input) return "";
  let s = input.toLocaleLowerCase("tr"); // İ→i, I→ı (Türkçe-güvenli)
  s = s.replace(/[ışğüöç]/g, (ch) => TR_FOLD[ch] ?? ch); // açık Türkçe fold
  s = s.normalize("NFD").replace(/[̀-ͯ]/g, ""); // kalan aksanları sil
  return s.trim();
}

/**
 * `text`, `query`'yi (aksan-duyarsız, Türkçe-güvenli) içeriyor mu?
 * Boş sorgu her zaman `true` döner.
 */
export function matchesSearch(
  text: string | null | undefined,
  query: string | null | undefined
): boolean {
  const q = normalizeForSearch(query);
  if (!q) return true;
  return normalizeForSearch(text).includes(q);
}

/**
 * Checks if `text` matches any whitespace-separated token in `query`.
 * Returns `true` if `query` is empty or if any token is found in `text`.
 * Full query match takes priority over token-level OR fallback.
 */
export function matchesAnyToken(
  text: string | null | undefined,
  query: string | null | undefined
): boolean {
  const q = normalizeForSearch(query);
  if (!q) return true;
  const normalizedText = normalizeForSearch(text);
  if (normalizedText.includes(q)) return true;
  return q.split(/\s+/).filter(Boolean).some((token) => normalizedText.includes(token));
}

const trCollator = new Intl.Collator("tr", {
  sensitivity: "base",
  numeric: true,
});

/**
 * Kullanıcı-görünür listeler için Türkçe alfabe + sayısal-duyarlı
 * karşılaştırma. `Array.prototype.sort` ile doğrudan kullanılabilir.
 *
 * `sensitivity: "base"` kullanıldığından aksan/büyük-küçük harf varyantları
 * sıralama açısından eşit sayılır — örneğin `"Şehir"` ile `"şehir"` berabere
 * gelir. Bu karşılaştırıcı görsel liste sıralaması içindir, kesin
 * aksan-farklılaştırmalı sıralama için değil.
 */
export function compareTr(a: string | null | undefined, b: string | null | undefined): number {
  return trCollator.compare(a ?? "", b ?? "");
}

/**
 * Fetch Timeout — T-25
 *
 * Wraps fetch() with an AbortController-based timeout.
 * Default timeout is 120 seconds (FETCH_TIMEOUT_MS env var).
 *
 * @module shared/utils/fetchTimeout
 */

const DEFAULT_TIMEOUT_MS =
  parseInt(process.env.OMNIROUTE_DEFAULT_FETCH_TIMEOUT_MS || "", 10) || 120000; // 2 minutes
const FETCH_TIMEOUT_MS = parseInt(process.env.FETCH_TIMEOUT_MS || "", 10) || DEFAULT_TIMEOUT_MS;

interface FetchTimeoutOptions extends RequestInit {
  timeoutMs?: number;
  /** Alternative fetch function to use instead of globalThis.fetch.
   *  Pass getOriginalFetch() to bypass the proxy/TLS patch layer. */
  fetchFn?: typeof globalThis.fetch;
}

export async function fetchWithTimeout(url: string | URL, options: FetchTimeoutOptions = {}) {
  const { timeoutMs = FETCH_TIMEOUT_MS, signal: externalSignal, fetchFn, ...fetchOptions } = options;

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  // If an external signal was provided, wire it to abort our controller too
  if (externalSignal) {
    if (externalSignal.aborted) {
      controller.abort();
    } else {
      externalSignal.addEventListener("abort", () => controller.abort(), { once: true });
    }
  }

  try {
    const doFetch = fetchFn || globalThis.fetch;
    const response = await doFetch(url, {
      ...fetchOptions,
      signal: controller.signal,
    });
    return response;
  } catch (error: any) {
    if (error.name === "AbortError") {
      throw new FetchTimeoutError(
        `Request to ${url} timed out after ${timeoutMs}ms`,
        timeoutMs,
        String(url)
      );
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Error thrown on fetch timeout.
 */
export class FetchTimeoutError extends Error {
  timeoutMs: number;
  url: string;

  constructor(message: string, timeoutMs: number, url: string) {
    super(message);
    this.name = "FetchTimeoutError";
    this.timeoutMs = timeoutMs;
    this.url = url;
  }
}

/**
 * Get the configured timeout value.
 * @returns {number} Timeout in milliseconds
 */
export function getConfiguredTimeout() {
  return FETCH_TIMEOUT_MS;
}

