/**
 * Get neighbors around a user on the leaderboard.
 */
export function getLeaderboardNeighbors(
  apiKeyId: string,
  scope: string,
  radius: number = 5
): {
  above: Array<{ apiKeyId: string; score: number }>;
  below: Array<{ apiKeyId: string; score: number }>;
} {
  const d = db();

  const scoreRow = d
    .prepare("SELECT score FROM leaderboard WHERE api_key_id = ? AND scope = ?")
    .get(apiKeyId, scope) as { score: number } | undefined;

  if (!scoreRow) return { above: [], below: [] };

  const above = d
    .prepare(
      `SELECT api_key_id, score FROM leaderboard
       WHERE scope = ? AND score > ?
       ORDER BY score ASC LIMIT ?`
    )
    .all(scope, scoreRow.score, radius) as Array<{ api_key_id: string; score: number }>;

  const below = d
    .prepare(
      `SELECT api_key_id, score FROM leaderboard
       WHERE scope = ? AND score < ?
       ORDER BY score DESC LIMIT ?`
    )
    .all(scope, scoreRow.score, radius) as Array<{ api_key_id: string; score: number }>;

  return {
    above: above.reverse().map((r) => ({ apiKeyId: r.api_key_id, score: r.score })),
    below: below.map((r) => ({ apiKeyId: r.api_key_id, score: r.score })),
  };
}

/**
 * Rotate weekly/monthly scopes. Archive old data, reset current.
 * Uses two-step approach (SELECT then parameterized INSERT) to avoid SQL injection.
 * Skips if archive scope already has data for this period (double-run protection).
 */
export function rotateLeaderboardScope(scope: "weekly" | "monthly"): void {
  const d = db();
  const archiveSuffix =
    scope === "weekly"
      ? `week_${new Date().toISOString().slice(0, 10)}`
      : `month_${new Date().toISOString().slice(0, 7)}`;

  // Double-run protection: skip if archive scope already has data
  const existing = d
    .prepare("SELECT COUNT(*) AS cnt FROM leaderboard WHERE scope = ?")
    .get(archiveSuffix) as { cnt: number };
  if (existing.cnt > 0) return;

  // Step 1: SELECT rows into memory
  const rows = d
    .prepare("SELECT api_key_id, score, updated_at FROM leaderboard WHERE scope = ?")
    .all(scope) as Array<{ api_key_id: string; score: number; updated_at: string }>;

  // Step 2: INSERT with parameters (no string interpolation)
  if (rows.length > 0) {
    const insert = d.prepare(
      "INSERT OR IGNORE INTO leaderboard (api_key_id, scope, score, updated_at) VALUES (?, ?, ?, ?)"
    );
    for (const row of rows) {
      insert.run(row.api_key_id, archiveSuffix, row.score, row.updated_at);
    }
  }

  d.prepare("DELETE FROM leaderboard WHERE scope = ?").run(scope);
}

/**
 * XP/Level Engine for OmniRoute Gamification
 *
 * Pure functions for XP calculations, level progression, and reward definitions.
 * No side effects or DB calls — all stateful logic lives in the persistence layer.
 */

// ─── XP Curve ────────────────────────────────────────────────────────────────

/**
 * XP required for a specific level (delta, not cumulative).
 * Polynomial curve: `xp_for_level(n) = floor(100 * n^1.5)`
 *
 * @param level - Target level (must be >= 1)
 * @returns XP needed to gain this level (0 for level 1)
 *
 * @example
 * xpForLevel(1)  // 0
 * xpForLevel(10) // 3162
 * xpForLevel(50) // 35355
 */
export function xpForLevel(level: number): number {
  if (level <= 1) return 0;
  return Math.floor(100 * Math.pow(level, 1.5));
}

/**
 * Cumulative XP required to reach a given level (sum of all prior level deltas).
 *
 * @param level - Target level (must be >= 1)
 * @returns Total XP accumulated by that level
 *
 * @example
 * cumulativeXpForLevel(1)  // 0
 * cumulativeXpForLevel(10) // sum of xpForLevel(2..10)
 */
export function cumulativeXpForLevel(level: number): number {
  if (level <= 1) return 0;
  let total = 0;
  for (let i = 2; i <= level; i++) {
    total += xpForLevel(i);
  }
  return total;
}

/**
 * Calculate level from total XP using the inverse of the cumulative XP curve.
 *
 * The cumulative XP for level L approximates to `100 * L^2.5 / 2.5`.
 * Solving for L gives `L ≈ (totalXp * 2.5 / 100) ^ 0.4`.
 *
 * @param totalXp - Total accumulated XP
 * @returns Current level (minimum 1)
 *
 * @example
 * calculateLevel(0)      // 1
 * calculateLevel(5000)   // ~8
 * calculateLevel(100000) // ~100
 */
export function calculateLevel(totalXp: number): number {
  if (totalXp <= 0) return 1;
  return Math.max(1, Math.floor(Math.pow((totalXp * 2.5) / 100, 0.4)));
}

/**
 * Get XP needed to reach the next level from the current total XP.
 *
 * @param totalXp - Current total XP
 * @returns Remaining XP until next level-up
 *
 * @example
 * xpToNextLevel(0)    // XP needed to reach level 2
 * xpToNextLevel(5000) // XP needed from 5000 to next level
 */
export function xpToNextLevel(totalXp: number): number {
  const currentLevel = calculateLevel(totalXp);
  const nextLevelXp = cumulativeXpForLevel(currentLevel + 1);
  return nextLevelXp - totalXp;
}

// ─── Level Titles & Tiers ────────────────────────────────────────────────────

/**
 * Get a human-readable title for a given level.
 *
 * @param level - Current level
 * @returns Level title string
 *
 * @example
 * getLevelTitle(5)   // "Beginner"
 * getLevelTitle(15)  // "Explorer"
 * getLevelTitle(30)  // "Expert"
 * getLevelTitle(60)  // "Master"
 * getLevelTitle(80)  // "Legend"
 */
export function getLevelTitle(level: number): string {
  if (level >= 76) return "Legend";
  if (level >= 51) return "Master";
  if (level >= 26) return "Expert";
  if (level >= 11) return "Explorer";
  return "Beginner";
}

/**
 * Get the badge tier for a given level.
 *
 * @param level - Current level
 * @returns Tier identifier suitable for badge display
 *
 * @example
 * getLevelTier(5)   // "bronze"
 * getLevelTier(20)  // "silver"
 * getLevelTier(40)  // "gold"
 * getLevelTier(60)  // "platinum"
 * getLevelTier(90)  // "diamond"
 */
export function getLevelTier(level: number): "bronze" | "silver" | "gold" | "platinum" | "diamond" {
  if (level >= 76) return "diamond";
  if (level >= 51) return "platinum";
  if (level >= 26) return "gold";
  if (level >= 11) return "silver";
  return "bronze";
}

