export function getEnabledMiddlewareHooks(): HookConfig[] {
  const db = getDbInstance() as any;
  const rows = db
    .prepare("SELECT * FROM middleware_hooks WHERE enabled = 1 ORDER BY priority ASC")
    .all() as HookConfigRow[];
  return rows.map(rowToHookConfig);
}

/**
 * Get scoped hooks for a given combo ID.
 */
export function getComboMiddlewareHooks(comboId: string): HookConfig[] {
  const db = getDbInstance() as any;
  const rows = db
    .prepare(
      "SELECT * FROM middleware_hooks WHERE enabled = 1 AND (scope_type = 'global' OR (scope_type = 'combo' AND combo_id = ?)) ORDER BY priority ASC"
    )
    .all(comboId) as HookConfigRow[];
  return rows.map(rowToHookConfig);
}

/**
 * Get a single hook by name.
 */
export function getMiddlewareHook(name: string): HookConfig | undefined {
  const db = getDbInstance() as any;
  const row = db.prepare("SELECT * FROM middleware_hooks WHERE name = ?").get(name) as
    | HookConfigRow
    | undefined;
  return row ? rowToHookConfig(row) : undefined;
}

/**
 * Create a new middleware hook.
 */
export function createMiddlewareHook(config: HookConfig): HookConfig {
  const db = getDbInstance() as any;
  const row = hookConfigToRow(config);
  row.created_at = new Date().toISOString();
  row.updated_at = row.created_at;

  db.prepare(
    `
    INSERT INTO middleware_hooks (name, description, priority, scope_type, combo_id, enabled, code, created_at, updated_at, run_count, last_error)
    VALUES (@name, @description, @priority, @scope_type, @combo_id, @enabled, @code, @created_at, @updated_at, @run_count, @last_error)
  `
  ).run(row);

  return getMiddlewareHook(config.name)!;
}

/**
 * Update an existing middleware hook.
 */
export function updateMiddlewareHook(
  name: string,
  updates: Partial<HookConfig>
): HookConfig | undefined {
  const existing = getMiddlewareHook(name);
  if (!existing) return undefined;

  const updated = { ...existing, ...updates, updatedAt: new Date().toISOString() };
  const row = hookConfigToRow(updated);
  const db = getDbInstance() as any;

  db.prepare(
    `
    UPDATE middleware_hooks SET
      description = @description,
      priority = @priority,
      scope_type = @scope_type,
      combo_id = @combo_id,
      enabled = @enabled,
      code = @code,
      updated_at = @updated_at,
      run_count = @run_count,
      last_error = @last_error
    WHERE name = @name
  `
  ).run(row);

  return getMiddlewareHook(name);
}

/**
 * Delete a middleware hook.
 */
export function deleteMiddlewareHook(name: string): boolean {
  const db = getDbInstance() as any;
  const result = db.prepare("DELETE FROM middleware_hooks WHERE name = ?").run(name);
  return result.changes > 0;
}

/**
 * Increment run count and optionally update last error.
 */
export function recordHookExecution(name: string, error?: string): void {
  const db = getDbInstance() as any;
  if (error) {
    db.prepare(
      "UPDATE middleware_hooks SET run_count = run_count + 1, last_error = ?, updated_at = datetime('now') WHERE name = ?"
    ).run(error, name);
  } else {
    db.prepare(
      "UPDATE middleware_hooks SET run_count = run_count + 1, last_error = NULL, updated_at = datetime('now') WHERE name = ?"
    ).run(name);
  }
}

// ── Log Operations ────────────────────────────────────────────────────────

/**
 * Insert a hook execution log entry.
 */
export function insertHookLog(entry: HookLogEntry): void {
  const db = getDbInstance() as any;
  db.prepare(
    `
    INSERT INTO middleware_logs (id, hook_name, request_id, duration_ms, mutated, skipped, error, timestamp)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?)
  `
  ).run(
    entry.id,
    entry.hookName,
    entry.requestId,
    entry.durationMs,
    entry.mutated ? 1 : 0,
    entry.skipped ? 1 : 0,
    entry.error || null,
    entry.timestamp
  );
}

/**
 * Get hook execution logs, optionally filtered by hook name.
 */
export function getHookLogs(hookName?: string, limit = 50): HookLogEntry[] {
  const db = getDbInstance() as any;
  let rows: any[];
  if (hookName) {
    rows = db
      .prepare("SELECT * FROM middleware_logs WHERE hook_name = ? ORDER BY timestamp DESC LIMIT ?")
      .all(hookName, limit);
  } else {
    rows = db.prepare("SELECT * FROM middleware_logs ORDER BY timestamp DESC LIMIT ?").all(limit);
  }
  return rows.map((r: any) => ({
    id: r.id,
    hookName: r.hook_name,
    requestId: r.request_id,
    durationMs: r.duration_ms,
    mutated: r.mutated === 1,
    skipped: r.skipped === 1,
    error: r.error,
    timestamp: r.timestamp,
  }));
}

/**
 * Clean up old hook logs (keep last N entries).
 */
export function cleanupHookLogs(maxEntries = 10000): number {
  const db = getDbInstance() as any;
  // Delete logs beyond the max, keeping the most recent
  const result = db
    .prepare(
      `
    DELETE FROM middleware_logs WHERE id NOT IN (
      SELECT id FROM middleware_logs ORDER BY timestamp DESC LIMIT ?
    )
  `
    )
    .run(maxEntries);
  return result.changes;
}

/**
 * Relay Proxy DB module
 *
 * Manages relay tokens, rate limits, and usage tracking for serverless relay proxies.
 */

import { randomBytes } from "node:crypto";
import { getDbInstance } from "./core";
import { rowToCamel } from "./core";

// ── Types ────────────────────────────────────────────────────────────────────

export interface RelayToken {
  id: string;
  name: string;
  tokenHash: string;
  tokenPrefix: string;
  description: string;
  comboId: string | null;
  allowedModels: string;
  maxTokensPerRequest: number;
  maxRequestsPerMinute: number;
  maxRequestsPerDay: number;
  maxCostPerDay: number;
  enabled: boolean;
  createdAt: number;
  updatedAt: number;
  expiresAt: number | null;
  lastUsedAt: number | null;
  metadata: string;
}

export interface RelayTokenRow {
  id: string;
  name: string;
  token_hash: string;
  token_prefix: string;
  description: string;
  combo_id: string | null;
  allowed_models: string;
  max_tokens_per_request: number;
  max_requests_per_minute: number;
  max_requests_per_day: number;
  max_cost_per_day: number;
  enabled: number;
  created_at: number;
  updated_at: number;
  expires_at: number | null;
  last_used_at: number | null;
  metadata: string;
}

export interface CreateRelayTokenInput {
  name: string;
  description?: string;
  comboId?: string;
  allowedModels?: string[];
  maxTokensPerRequest?: number;
  maxRequestsPerMinute?: number;
  maxRequestsPerDay?: number;
  maxCostPerDay?: number;
  expiresAt?: number;
  metadata?: Record<string, unknown>;
}

export interface RelayTokenWithSecret extends RelayToken {
  rawToken: string; // Only returned once on creation
}

export interface RelayLogRow {
  id: number;
  token_id: string;
  request_id: string | null;
  model: string | null;
  prompt_tokens: number;
  completion_tokens: number;
  cost: number;
  status: string;
  status_code: number;
  latency_ms: number;
  client_ip: string | null;
  user_agent: string | null;
  created_at: number;
}

// ── Helpers ──────────────────────────────────────────────────────────────────

function generateId(): string {
  return "rl_" + randomBytes(16).toString("hex");
}

function generateToken(): string {
  return "relay_" + randomBytes(24).toString("hex");
}

function hashToken(token: string): string {
  // Simple hash for token comparison (not bcrypt-heavy for performance)
  const { createHash } = require("node:crypto");
  return createHash("sha256").update(token).digest("hex");
}

// ── CRUD ─────────────────────────────────────────────────────────────────────

export function createRelayToken(input: CreateRelayTokenInput): RelayTokenWithSecret {
  const db = getDbInstance();
  const id = generateId();
  const rawToken = generateToken();
  const tokenHash = hashToken(rawToken);
  const now = Math.floor(Date.now() / 1000);

  const prefix = "rl_" + rawToken.slice(6, 14);

  db.prepare(
    `
    INSERT INTO relay_tokens (id, name, token_hash, token_prefix, description, combo_id, allowed_models,
      max_tokens_per_request, max_requests_per_minute, max_requests_per_day, max_cost_per_day,
      enabled, created_at, updated_at, expires_at, metadata)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?, ?)
  `
  ).run(
    id,
    input.name,
    tokenHash,
    prefix,
    input.description || "",
    input.comboId || null,
    JSON.stringify(input.allowedModels || ["*"]),
    input.maxTokensPerRequest || 128000,
    input.maxRequestsPerMinute || 60,
    input.maxRequestsPerDay || 10000,
    input.maxCostPerDay || 0,
    now,
    now,
    input.expiresAt || null,
    JSON.stringify(input.metadata || {})
  );

  const token = db.prepare("SELECT * FROM relay_tokens WHERE id = ?").get(id) as RelayTokenRow;
  return { ...(rowToCamel(token) as unknown as RelayToken), rawToken };
}

export function getRelayTokens(): RelayToken[] {
  const db = getDbInstance();
  const rows = db
    .prepare("SELECT * FROM relay_tokens ORDER BY created_at DESC")
    .all() as RelayTokenRow[];
  return rows.map((r) => ({
    ...(rowToCamel(r) as unknown as RelayToken),
    enabled: r.enabled === 1,
  }));
}

export function getRelayToken(id: string): RelayToken | null {
  const db = getDbInstance();
  const row = db.prepare("SELECT * FROM relay_tokens WHERE id = ?").get(id) as
    RelayTokenRow | undefined;
  if (!row) return null;
  return { ...(rowToCamel(row) as unknown as RelayToken), enabled: row.enabled === 1 };
}

export function getRelayTokenByHash(
  tokenHash: string
): (RelayToken & { rawToken?: string }) | null {
  const db = getDbInstance();
  const row = db
    .prepare("SELECT * FROM relay_tokens WHERE token_hash = ? AND enabled = 1")
    .get(tokenHash) as RelayTokenRow | undefined;
  if (!row) return null;
  return { ...(rowToCamel(row) as unknown as RelayToken), enabled: row.enabled === 1 };
}

export function updateRelayToken(
  id: string,
  updates: Partial<CreateRelayTokenInput>
): RelayToken | null {
  const db = getDbInstance();
  const now = Math.floor(Date.now() / 1000);
  const sets: string[] = ["updated_at = ?"];
  const params: unknown[] = [now];

  if (updates.name !== undefined) {
    sets.push("name = ?");
    params.push(updates.name);
  }
  if (updates.description !== undefined) {
    sets.push("description = ?");
    params.push(updates.description);
  }
  if (updates.comboId !== undefined) {
    sets.push("combo_id = ?");
    params.push(updates.comboId);
  }
  if (updates.allowedModels !== undefined) {
    sets.push("allowed_models = ?");
    params.push(JSON.stringify(updates.allowedModels));
  }
  if (updates.maxTokensPerRequest !== undefined) {
    sets.push("max_tokens_per_request = ?");
    params.push(updates.maxTokensPerRequest);
  }
  if (updates.maxRequestsPerMinute !== undefined) {
    sets.push("max_requests_per_minute = ?");
    params.push(updates.maxRequestsPerMinute);
  }
  if (updates.maxRequestsPerDay !== undefined) {
    sets.push("max_requests_per_day = ?");
    params.push(updates.maxRequestsPerDay);
  }
  if (updates.maxCostPerDay !== undefined) {
    sets.push("max_cost_per_day = ?");
    params.push(updates.maxCostPerDay);
  }

  params.push(id);
  db.prepare(`UPDATE relay_tokens SET ${sets.join(", ")} WHERE id = ?`).run(...params);
  return getRelayToken(id);
}

export function deleteRelayToken(id: string): void {
  const db = getDbInstance();
  db.prepare("DELETE FROM relay_tokens WHERE id = ?").run(id);
}

export function toggleRelayToken(id: string, enabled: boolean): RelayToken | null {
  const db = getDbInstance();
  const now = Math.floor(Date.now() / 1000);
  db.prepare("UPDATE relay_tokens SET enabled = ?, updated_at = ? WHERE id = ?").run(
    enabled ? 1 : 0,
    now,
    id
  );
  return getRelayToken(id);
}

// ── Usage / Rate Limit ───────────────────────────────────────────────────────

export function checkRateLimit(
  tokenId: string,
  existingToken?: RelayToken
): {
  allowed: boolean;
  remaining: number;
  resetIn: number;
} {
  const db = getDbInstance();
  let token = existingToken;
  if (!token) {
    const row = db.prepare("SELECT * FROM relay_tokens WHERE id = ?").get(tokenId) as
      RelayTokenRow | undefined;
    if (!row) return { allowed: false, remaining: 0, resetIn: 0 };
    token = rowToCamel(row) as unknown as RelayToken;
  }

  const now = Math.floor(Date.now() / 1000);
  const minuteWindow = Math.floor(now / 60) * 60;
  const dayWindow = Math.floor(now / 86400) * 86400;

  // Check minute rate
  const minuteRow = db
    .prepare(
      "SELECT request_count, cost FROM relay_rate_limits WHERE token_id = ? AND window_start = ?"
    )
    .get(tokenId, minuteWindow) as { request_count: number; cost: number } | undefined;

  const minuteCount = minuteRow?.request_count || 0;
  if (minuteCount >= token.maxRequestsPerMinute) {
    return { allowed: false, remaining: 0, resetIn: 60 - (now % 60) };
  }

  // Check daily rate
  const dayRow = db
    .prepare(
      "SELECT SUM(request_count) as total FROM relay_rate_limits WHERE token_id = ? AND window_start >= ?"
    )
    .get(tokenId, dayWindow) as { total: number } | undefined;

  const dayCount = dayRow?.total || 0;
  if (dayCount >= token.maxRequestsPerDay) {
    return { allowed: false, remaining: 0, resetIn: 86400 - (now % 86400) };
  }

  const remaining = Math.min(
    token.maxRequestsPerMinute - minuteCount,
    token.maxRequestsPerDay - dayCount
  );

  return { allowed: true, remaining, resetIn: 60 - (now % 60) };
}

export function recordRelayUsage(
  tokenId: string,
  params: {
    requestId?: string;
    model?: string;
    promptTokens?: number;
    completionTokens?: number;
    cost?: number;
    status?: string;
    statusCode?: number;
    latencyMs?: number;
    clientIp?: string;
    userAgent?: string;
  }
): void {
  const db = getDbInstance();
  const now = Math.floor(Date.now() / 1000);
  const minuteWindow = Math.floor(now / 60) * 60;

  // Update rate limit window
  db.prepare(
    `
    INSERT INTO relay_rate_limits (token_id, window_start, request_count, cost)
    VALUES (?, ?, 1, ?)
    ON CONFLICT(token_id, window_start) DO UPDATE SET
      request_count = request_count + 1,
      cost = cost + ?
  `
  ).run(tokenId, minuteWindow, params.cost || 0, params.cost || 0);

  // Update last_used_at
  db.prepare("UPDATE relay_tokens SET last_used_at = ? WHERE id = ?").run(now, tokenId);

  // Insert log
  db.prepare(
    `
    INSERT INTO relay_logs (token_id, request_id, model, prompt_tokens, completion_tokens, cost,
      status, status_code, latency_ms, client_ip, user_agent, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
  `
  ).run(
    tokenId,
    params.requestId || null,
    params.model || null,
    params.promptTokens || 0,
    params.completionTokens || 0,
    params.cost || 0,
    params.status || "success",
    params.statusCode || 200,
    params.latencyMs || 0,
    params.clientIp || null,
    params.userAgent || null,
    now
  );
}

export function getRelayUsage(
  tokenId: string,
  since: number
): { requestCount: number; totalCost: number } {
  const db = getDbInstance();
  const row = db
    .prepare(
      "SELECT COUNT(*) as request_count, COALESCE(SUM(cost), 0) as total_cost FROM relay_logs WHERE token_id = ? AND created_at >= ?"
    )
    .get(tokenId, since) as { request_count: number; total_cost: number };
  return { requestCount: row.request_count, totalCost: row.total_cost };
}

export function getRelayLogs(tokenId?: string, limit = 50): RelayLogRow[] {
  const db = getDbInstance();
  if (tokenId) {
    return db
      .prepare("SELECT * FROM relay_logs WHERE token_id = ? ORDER BY created_at DESC LIMIT ?")
      .all(tokenId, limit) as RelayLogRow[];
  }
  return db
    .prepare("SELECT * FROM relay_logs ORDER BY created_at DESC LIMIT ?")
    .all(limit) as RelayLogRow[];
}

import { randomUUID } from "crypto";
import { getDbInstance } from "./core";
import { backupDbFile } from "./backup";
import type { FreeProxyItem, FreeProxySourceId } from "@/lib/freeProxyProviders/types";

export interface FreeProxyRecord {
  id: string;
  source: FreeProxySourceId;
  host: string;
  port: number;
  type: string;
  countryCode: string | null;
  qualityScore: number | null;
  latencyMs: number | null;
  anonymity: string | null;
  lastValidated: string | null;
  inPool: boolean;
  poolProxyId: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FreeProxyStats {
  total: number;
  inPool: number;
  avgQuality: number | null;
  bySource: Array<{ source: string; count: number }>;
  lastSyncAt: string | null;
}

/** Source id → list of error messages from that source's last sync. */
export type FreeProxySyncErrors = Record<string, string[]>;

type DbRow = Record<string, unknown>;

function mapRow(row: unknown): FreeProxyRecord {
  const r = row as DbRow;
  return {
    id: String(r.id ?? ""),
    source: String(r.source ?? "1proxy") as FreeProxySourceId,
    host: String(r.host ?? ""),
    port: Number(r.port) || 0,
    type: String(r.type ?? "http"),
    countryCode: r.country_code != null ? String(r.country_code) : null,
    qualityScore: r.quality_score != null ? Number(r.quality_score) : null,
    latencyMs: r.latency_ms != null ? Number(r.latency_ms) : null,
    anonymity: r.anonymity != null ? String(r.anonymity) : null,
    lastValidated: r.last_validated != null ? String(r.last_validated) : null,
    inPool: r.in_pool === 1 || r.in_pool === true,
    poolProxyId: r.pool_proxy_id != null ? String(r.pool_proxy_id) : null,
    createdAt: String(r.created_at ?? ""),
    updatedAt: String(r.updated_at ?? ""),
  };
}

export async function upsertFreeProxy(
  item: FreeProxyItem
): Promise<{ id: string; action: "created" | "updated" }> {
  const db = getDbInstance();
  const now = new Date().toISOString();

  const existing = db
    .prepare("SELECT id FROM free_proxies WHERE source = ? AND host = ? AND port = ?")
    .get(item.source, item.host, item.port) as { id?: string } | undefined;

  if (existing?.id) {
    db.prepare(
      `UPDATE free_proxies
       SET type = ?, country_code = ?, quality_score = ?, latency_ms = ?,
           anonymity = ?, last_validated = ?, updated_at = ?
       WHERE id = ?`
    ).run(
      item.type,
      item.countryCode ?? null,
      item.qualityScore ?? null,
      item.latencyMs ?? null,
      item.anonymity ?? null,
      item.lastValidated ?? now,
      now,
      existing.id
    );
    return { id: existing.id, action: "updated" };
  }

  const id = randomUUID();
  db.prepare(
    `INSERT INTO free_proxies
     (id, source, host, port, type, country_code, quality_score, latency_ms,
      anonymity, last_validated, in_pool, pool_proxy_id, created_at, updated_at)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 0, NULL, ?, ?)`
  ).run(
    id,
    item.source,
    item.host,
    item.port,
    item.type,
    item.countryCode ?? null,
    item.qualityScore ?? null,
    item.latencyMs ?? null,
    item.anonymity ?? null,
    item.lastValidated ?? now,
    now,
    now
  );
  return { id, action: "created" };
}

export async function listFreeProxies(options?: {
  sources?: FreeProxySourceId[];
  protocol?: string;
  country?: string;
  minQuality?: number;
  onlyInPool?: boolean;
  onlyNotInPool?: boolean;
  search?: string;
  sortBy?: "quality" | "latency" | "recent";
  limit?: number;
  offset?: number;
}): Promise<FreeProxyRecord[]> {
  const db = getDbInstance();
  const params: unknown[] = [];
  let sql = "SELECT * FROM free_proxies WHERE 1=1";

  if (options?.sources?.length) {
    sql += ` AND source IN (${options.sources.map(() => "?").join(",")})`;
    params.push(...options.sources);
  }
  if (options?.protocol) {
    sql += " AND type = ?";
    params.push(options.protocol);
  }
  if (options?.country) {
    sql += " AND country_code = ?";
    params.push(options.country.toUpperCase());
  }
  if (options?.minQuality != null) {
    sql += " AND quality_score >= ?";
    params.push(options.minQuality);
  }
  if (options?.onlyInPool) {
    sql += " AND in_pool = 1";
  }
  if (options?.onlyNotInPool) {
    sql += " AND in_pool = 0";
  }
  if (options?.search) {
    sql += " AND host LIKE ?";
    params.push(`%${options.search}%`);
  }

  const sortClause =
    options?.sortBy === "latency"
      ? "ORDER BY latency_ms IS NULL, latency_ms ASC"
      : options?.sortBy === "recent"
        ? "ORDER BY last_validated DESC"
        : "ORDER BY quality_score DESC, last_validated DESC";
  sql += ` ${sortClause}`;

  if (options?.limit) {
    sql += " LIMIT ?";
    params.push(options.limit);
    if (options?.offset) {
      sql += " OFFSET ?";
      params.push(options.offset);
    }
  }

  const rows = db.prepare(sql).all(...params);
  return rows.map(mapRow);
}

export async function countFreeProxies(options?: {
  sources?: FreeProxySourceId[];
  protocol?: string;
  country?: string;
  minQuality?: number;
  onlyInPool?: boolean;
  onlyNotInPool?: boolean;
  search?: string;
}): Promise<number> {
  const db = getDbInstance();
  const params: unknown[] = [];
  let sql = "SELECT COUNT(*) AS count FROM free_proxies WHERE 1=1";

  if (options?.sources?.length) {
    sql += ` AND source IN (${options.sources.map(() => "?").join(",")})`;
    params.push(...options.sources);
  }
  if (options?.protocol) {
    sql += " AND type = ?";
    params.push(options.protocol);
  }
  if (options?.country) {
    sql += " AND country_code = ?";
    params.push(options.country.toUpperCase());
  }
  if (options?.minQuality != null) {
    sql += " AND quality_score >= ?";
    params.push(options.minQuality);
  }
  if (options?.onlyInPool) {
    sql += " AND in_pool = 1";
  }
  if (options?.onlyNotInPool) {
    sql += " AND in_pool = 0";
  }
  if (options?.search) {
    sql += " AND host LIKE ?";
    params.push(`%${options.search}%`);
  }

  const row = db.prepare(sql).get(...params) as DbRow | undefined;
  const count = row?.count;
  return typeof count === "number" ? count : Number(count ?? 0);
}

export async function listFreeProxiesBySource(
  source: FreeProxySourceId,
  filters: {
    protocol?: string;
    country?: string;
    minQuality?: number;
    limit?: number;
  }
): Promise<FreeProxyItem[]> {
  const records = await listFreeProxies({
    sources: [source],
    protocol: filters.protocol,
    country: filters.country,
    minQuality: filters.minQuality,
    limit: filters.limit,
  });
  return records.map((r) => ({
    source: r.source,
    host: r.host,
    port: r.port,
    type: r.type as FreeProxyItem["type"],
    countryCode: r.countryCode,
    qualityScore: r.qualityScore,
    latencyMs: r.latencyMs,
    anonymity: r.anonymity,
    lastValidated: r.lastValidated,
  }));
}

export async function getFreeProxyById(id: string): Promise<FreeProxyRecord | null> {
  const db = getDbInstance();
  const row = db.prepare("SELECT * FROM free_proxies WHERE id = ?").get(id);
  return row ? mapRow(row) : null;
}

export async function markFreeProxyInPool(id: string, poolProxyId: string): Promise<void> {
  const db = getDbInstance();
  const now = new Date().toISOString();
  db.prepare(
    "UPDATE free_proxies SET in_pool = 1, pool_proxy_id = ?, updated_at = ? WHERE id = ?"
  ).run(poolProxyId, now, id);
  backupDbFile("pre-write");
}

/**
 * Atomically inserts the free proxy into `proxy_registry` and flips its
 * `in_pool` flag in a single SQLite transaction. Replaces the previous
 * non-atomic `createProxy() + markFreeProxyInPool()` pair which could leave
 * `free_proxies.in_pool=0` while the registry row already existed if the
 * second call failed.
 *
 * Returns the new `poolProxyId` on success, or `null` if the free proxy id
 * does not exist (caller should return 404).
 */
export async function promoteFreeProxyToPool(
  freeProxyId: string,
  registryPayload: {
    name: string;
    type: string;
    host: string;
    port: number;
    source: string;
  }
): Promise<string | null> {
  const db = getDbInstance();
  const now = new Date().toISOString();
  const newRegistryId = randomUUID();

  const result = db.transaction(() => {
    const exists = db
      .prepare("SELECT id, in_pool FROM free_proxies WHERE id = ? LIMIT 1")
      .get(freeProxyId) as { id?: string; in_pool?: number } | undefined;
    if (!exists?.id) return null;

    db.prepare(
      `INSERT INTO proxy_registry
        (id, name, type, host, port, username, password, region, notes, status, source, created_at, updated_at)
        VALUES (?, ?, ?, ?, ?, '', '', NULL, NULL, 'active', ?, ?, ?)`
    ).run(
      newRegistryId,
      registryPayload.name,
      registryPayload.type,
      registryPayload.host,
      Number(registryPayload.port),
      registryPayload.source,
      now,
      now
    );

    db.prepare(
      "UPDATE free_proxies SET in_pool = 1, pool_proxy_id = ?, updated_at = ? WHERE id = ?"
    ).run(newRegistryId, now, freeProxyId);

    return newRegistryId;
  })();

  if (result) backupDbFile("pre-write");
  return result;
}

export async function deleteFreeProxy(id: string): Promise<boolean> {
  const db = getDbInstance();
  const result = db.prepare("DELETE FROM free_proxies WHERE id = ?").run(id);
  backupDbFile("pre-write");
  return result.changes > 0;
}

export async function clearFreeProxiesBySource(source: FreeProxySourceId): Promise<number> {
  const db = getDbInstance();
  const result = db
    .prepare("DELETE FROM free_proxies WHERE source = ? AND in_pool = 0")
    .run(source);
  backupDbFile("pre-write");
  return result.changes;
}

/**
 * Tombstone rows for `source` whose `host:port` is no longer present in the
 * provider's latest list — e.g. Webshare recycles/retires proxy IDs between
 * syncs. Rows already promoted to the pool (`in_pool = 1`) are left alone so
 * runtime resolution of an in-use proxy is never disturbed; only stale,
 * not-yet-pooled candidates are pruned. Returns the number of rows removed.
 */
export async function pruneStaleFreeProxies(
  source: FreeProxySourceId,
  activeKeys: ReadonlySet<string>
): Promise<number> {
  const db = getDbInstance();
  const rows = db
    .prepare("SELECT id, host, port FROM free_proxies WHERE source = ? AND in_pool = 0")
    .all(source) as Array<{ id: string; host: string; port: number }>;

  const staleIds = rows.filter((r) => !activeKeys.has(`${r.host}:${r.port}`)).map((r) => r.id);

  if (staleIds.length === 0) return 0;

  const placeholders = staleIds.map(() => "?").join(",");
  const result = db
    .prepare(`DELETE FROM free_proxies WHERE id IN (${placeholders})`)
    .run(...staleIds);
  backupDbFile("pre-write");
  return result.changes;
}

// #4878: the displayed "last sync" used to be derived from MAX(last_validated),
// which only advances when a provider returns at least one new/updated proxy. A
// sync that returns zero rows (or whose providers all fail) left the timestamp
// frozen, so "Sync All" appeared to do nothing. We persist an explicit sync
// timestamp in the generic key_value store and prefer it in the stats.
const FREE_PROXY_SYNC_NAMESPACE = "free_proxies";
const FREE_PROXY_SYNC_KEY = "last_sync_at";

/**
 * Persist the moment a free-proxy sync completed. Returns the stored ISO string
 * so the route can echo it back. `at` is overridable for deterministic tests.
 */
export async function recordFreeProxySync(at?: string): Promise<string> {
  const db = getDbInstance();
  const ts = at ?? new Date().toISOString();
  db.prepare("INSERT OR REPLACE INTO key_value (namespace, key, value) VALUES (?, ?, ?)").run(
    FREE_PROXY_SYNC_NAMESPACE,
    FREE_PROXY_SYNC_KEY,
    ts
  );
  backupDbFile("pre-write");
  return ts;
}

function getRecordedFreeProxySync(db: ReturnType<typeof getDbInstance>): string | null {
  const row = db
    .prepare("SELECT value FROM key_value WHERE namespace = ? AND key = ?")
    .get(FREE_PROXY_SYNC_NAMESPACE, FREE_PROXY_SYNC_KEY) as { value?: string } | undefined;
  return row?.value != null ? String(row.value) : null;
}

export async function getFreeProxyStats(): Promise<FreeProxyStats> {
  const db = getDbInstance();
  const totals = db
    .prepare(
      `SELECT COUNT(*) as total,
              SUM(CASE WHEN in_pool = 1 THEN 1 ELSE 0 END) as in_pool_count,
              AVG(quality_score) as avg_quality,
              MAX(last_validated) as last_sync_at
       FROM free_proxies`
    )
    .get() as DbRow;

  const bySource = db
    .prepare(
      "SELECT source, COUNT(*) as count FROM free_proxies GROUP BY source ORDER BY count DESC"
    )
    .all() as DbRow[];

  // Prefer the explicitly recorded sync timestamp (#4878); fall back to the
  // newest last_validated only when no sync has ever been recorded.
  const recordedSyncAt = getRecordedFreeProxySync(db);
  const derivedSyncAt = totals.last_sync_at != null ? String(totals.last_sync_at) : null;

  return {
    total: Number(totals.total) || 0,
    inPool: Number(totals.in_pool_count) || 0,
    avgQuality: totals.avg_quality != null ? Math.round(Number(totals.avg_quality)) : null,
    bySource: bySource.map((r) => ({ source: String(r.source), count: Number(r.count) })),
    lastSyncAt: recordedSyncAt ?? derivedSyncAt,
  };
}
/**
 * Persist the most recent per-source sync errors. A successful sync for a
 * source should call clearFreeProxySyncErrors instead so the stale error
 * stops showing.
 */
export async function recordFreeProxySyncErrors(
  source: FreeProxySourceId,
  errors: string[]
): Promise<void> {
  const db = getDbInstance();
  const at = new Date().toISOString();
  db.prepare(
    "INSERT OR REPLACE INTO free_proxy_sync_errors (source, errors, updated_at) VALUES (?, ?, ?)"
  ).run(source, JSON.stringify(errors), at);
  backupDbFile("pre-write");
}

/** Clear a source's stored sync error (called on a successful sync). */
export async function clearFreeProxySyncErrors(source: FreeProxySourceId): Promise<void> {
  const db = getDbInstance();
  db.prepare("DELETE FROM free_proxy_sync_errors WHERE source = ?").run(source);
  backupDbFile("pre-write");
}

/**
 * Read all stored per-source sync errors as a plain map. Sources with no
 * recorded error are omitted, so an empty object means a clean (or un-synced)
 * state.
 */
export async function getFreeProxySyncErrors(): Promise<FreeProxySyncErrors> {
  const db = getDbInstance();
  const rows = db.prepare("SELECT source, errors FROM free_proxy_sync_errors").all() as Array<{
    source: string;
    errors: string;
  }>;
  const out: FreeProxySyncErrors = {};
  for (const row of rows) {
    if (!row.source) continue;
    try {
      const parsed = JSON.parse(row.errors) as unknown;
      out[row.source] = Array.isArray(parsed) ? parsed.map(String) : [String(row.errors)];
    } catch {
      out[row.source] = [String(row.errors)];
    }
  }
  return out;
}

/**
 * db/playgroundPresets.ts — Playground Studio preset persistence.
 *
 * CRUD operations for the playground_presets table (migration 076).
 * All queries use db.prepare() (better-sqlite3) — never raw db.exec() or
 * string interpolation.
 *
 * @module lib/db/playgroundPresets
 */

import { getDbInstance } from "./core";
import { randomUUID } from "node:crypto";

// TODO(F1-merge): swap to import from "@/shared/schemas/playground" after F1 lands
export interface PlaygroundPresetListItem {
  id: string;
  name: string;
  endpoint: string;
  model: string;
  system: string | null;
  params: Record<string, unknown>;
  created_at: string;
}

type PlaygroundPresetRow = {
  id: string;
  name: string;
  endpoint: string;
  model: string;
  system: string | null;
  params_json: string;
  created_at: string;
};

function rowToItem(row: PlaygroundPresetRow): PlaygroundPresetListItem {
  let params: Record<string, unknown> = {};
  try {
    const parsed = JSON.parse(row.params_json);
    if (parsed !== null && typeof parsed === "object" && !Array.isArray(parsed)) {
      params = parsed as Record<string, unknown>;
    }
  } catch {
    params = {};
  }
  return {
    id: row.id,
    name: row.name,
    endpoint: row.endpoint,
    model: row.model,
    system: row.system,
    params,
    created_at: row.created_at,
  };
}

/**
 * Returns all presets ordered by created_at descending (newest first).
 * Accepts optional limit/offset for pagination.
 */
export function listPlaygroundPresets(options?: { limit?: number; offset?: number }): {
  items: PlaygroundPresetListItem[];
  total: number;
} {
  const db = getDbInstance();
  const limit = options?.limit;
  const offset = options?.offset ?? 0;
  let sql = "SELECT * FROM playground_presets ORDER BY created_at DESC";
  const params: unknown[] = [];
  if (limit !== undefined) {
    sql += " LIMIT ? OFFSET ?";
    params.push(limit, offset);
  }
  const rows = db.prepare(sql).all(...params) as PlaygroundPresetRow[];
  const totalRow = db.prepare("SELECT count(*) as cnt FROM playground_presets").get() as {
    cnt: number;
  };
  return { items: rows.map(rowToItem), total: totalRow.cnt };
}

/**
 * Returns a single preset by id, or null when not found.
 */
export function getPlaygroundPreset(id: string): PlaygroundPresetListItem | null {
  const db = getDbInstance();
  const row = db.prepare("SELECT * FROM playground_presets WHERE id = ? LIMIT 1").get(id) as
    PlaygroundPresetRow | undefined;
  if (!row) return null;
  return rowToItem(row);
}

/**
 * Creates a new preset. Generates a UUID v4 for the id.
 * Returns the persisted row via getPlaygroundPreset.
 */
export function createPlaygroundPreset(input: {
  name: string;
  endpoint: string;
  model: string;
  system: string | null | undefined;
  params: Record<string, unknown>;
}): PlaygroundPresetListItem {
  const db = getDbInstance();
  const id = randomUUID();
  const params_json = JSON.stringify(input.params ?? {});
  const system = input.system ?? null;

  db.prepare(
    "INSERT INTO playground_presets (id, name, endpoint, model, system, params_json) VALUES (?, ?, ?, ?, ?, ?)"
  ).run(id, input.name, input.endpoint, input.model, system, params_json);

  const created = getPlaygroundPreset(id);
  // created cannot be null here — we just inserted the row
  return created as PlaygroundPresetListItem;
}

/**
 * Updates only the supplied fields on an existing preset.
 * Returns the updated row, or null when the id does not exist.
 */
export function updatePlaygroundPreset(
  id: string,
  patch: Partial<{
    name: string;
    endpoint: string;
    model: string;
    system: string | null;
    params: Record<string, unknown>;
  }>
): PlaygroundPresetListItem | null {
  const db = getDbInstance();

  // Verify row exists before building the dynamic UPDATE
  const existing = getPlaygroundPreset(id);
  if (!existing) return null;

  const setClauses: string[] = [];
  const values: unknown[] = [];

  if (patch.name !== undefined) {
    setClauses.push("name = ?");
    values.push(patch.name);
  }
  if (patch.endpoint !== undefined) {
    setClauses.push("endpoint = ?");
    values.push(patch.endpoint);
  }
  if (patch.model !== undefined) {
    setClauses.push("model = ?");
    values.push(patch.model);
  }
  if ("system" in patch) {
    setClauses.push("system = ?");
    values.push(patch.system ?? null);
  }
  if (patch.params !== undefined) {
    setClauses.push("params_json = ?");
    values.push(JSON.stringify(patch.params));
  }

  if (setClauses.length === 0) {
    // Empty patch — return current row unchanged
    return existing;
  }

  values.push(id);
  db.prepare(`UPDATE playground_presets SET ${setClauses.join(", ")} WHERE id = ?`).run(...values);

  return getPlaygroundPreset(id);
}

/**
 * Deletes a preset by id.
 * Returns true when a row was deleted, false when the id did not exist.
 */
export function deletePlaygroundPreset(id: string): boolean {
  const db = getDbInstance();
  const result = db.prepare("DELETE FROM playground_presets WHERE id = ?").run(id);
  return result.changes > 0;
}

/**
 * db/memoryVec.ts — CRUD for memory vector metadata and reindex state.
 *
 * Plan 21 — Memory Engine Redesign.
 * Raw SQL is allowed here (Hard Rule #5 — src/lib/db/ domain module).
 *
 * This module manages:
 *   - `memory_vec_meta`: singleton row tracking the active embedding dim/signature/reset
 *   - `memories.needs_reindex`: flag for lazy backfill of missing/stale vectors
 */

import { getDbInstance } from "./core";

// ──────────────── Types ────────────────

export interface MemoryVecMeta {
  activeDim: number | null;
  embeddingSignature: string | null;
  lastResetAt: string | null;
  vecLoaded: boolean;
}

// ──────────────── memory_vec_meta ────────────────

/**
 * Get the singleton memory_vec_meta row.
 * Returns defaults if the row is absent (e.g. migration not yet applied on
 * an in-memory test DB that ran without the migration file).
 */
export function getMemoryVecMeta(): MemoryVecMeta {
  const db = getDbInstance();
  const row = db
    .prepare(
      "SELECT active_dim, embedding_signature, last_reset_at, vec_loaded FROM memory_vec_meta WHERE id = 1"
    )
    .get() as
    | {
        active_dim: number | null;
        embedding_signature: string | null;
        last_reset_at: string | null;
        vec_loaded: number;
      }
    | undefined;

  if (!row) {
    return {
      activeDim: null,
      embeddingSignature: null,
      lastResetAt: null,
      vecLoaded: false,
    };
  }

  return {
    activeDim: row.active_dim,
    embeddingSignature: row.embedding_signature,
    lastResetAt: row.last_reset_at,
    vecLoaded: row.vec_loaded === 1,
  };
}

/**
 * Update one or more fields in the singleton memory_vec_meta row.
 * Uses INSERT OR REPLACE to handle the case where the row is missing
 * (e.g. called before or during migration on a test DB).
 */
export function setMemoryVecMeta(meta: Partial<MemoryVecMeta>): void {
  const db = getDbInstance();

  // Read current values first so we can merge (partial update pattern).
  const current = getMemoryVecMeta();

  const activeDim = "activeDim" in meta ? meta.activeDim ?? null : current.activeDim;
  const embeddingSignature =
    "embeddingSignature" in meta
      ? meta.embeddingSignature ?? null
      : current.embeddingSignature;
  const lastResetAt =
    "lastResetAt" in meta ? meta.lastResetAt ?? null : current.lastResetAt;
  const vecLoaded =
    "vecLoaded" in meta ? (meta.vecLoaded ? 1 : 0) : current.vecLoaded ? 1 : 0;

  db.prepare(
    `INSERT OR REPLACE INTO memory_vec_meta
       (id, active_dim, embedding_signature, last_reset_at, vec_loaded)
     VALUES (1, ?, ?, ?, ?)`
  ).run(activeDim, embeddingSignature, lastResetAt, vecLoaded);
}

// ──────────────── memories.needs_reindex ────────────────

/**
 * Mark a single memory as needing reindex (or clear the flag).
 */
export function markMemoryNeedsReindex(id: string, needs: boolean): void {
  const db = getDbInstance();
  db.prepare("UPDATE memories SET needs_reindex = ? WHERE id = ?").run(needs ? 1 : 0, id);
}

/**
 * Mark ALL memories as needing reindex.
 * Returns the number of rows affected.
 */
export function markAllMemoriesNeedReindex(): number {
  const db = getDbInstance();
  const result = db.prepare("UPDATE memories SET needs_reindex = 1").run();
  return result.changes;
}

/**
 * Get a batch of memories that need reindex, ordered by creation date ascending.
 * Returns id, content, and key for each memory so the vector can be regenerated.
 */
export function getMemoryReindexQueue(
  limit: number
): Array<{ id: string; content: string; key: string }> {
  const db = getDbInstance();
  return db
    .prepare(
      `SELECT id, content, COALESCE(key, '') AS key
       FROM memories
       WHERE needs_reindex = 1
       ORDER BY created_at ASC
       LIMIT ?`
    )
    .all(limit) as Array<{ id: string; content: string; key: string }>;
}

/**
 * Count how many memories currently have needs_reindex = 1.
 */
export function countMemoryReindexPending(): number {
  const db = getDbInstance();
  const row = db
    .prepare("SELECT COUNT(*) AS cnt FROM memories WHERE needs_reindex = 1")
    .get() as { cnt: number };
  return row.cnt;
}

/**
 * Database module: AgentBridgeState
 * CRUD operations for agent_bridge_state table.
 */

import { getDbInstance } from "./core.ts";
import type { AgentBridgeStateRow } from "./_rowTypes.ts";

// SQLite stores booleans as 0/1 integers
interface AgentBridgeStateDbRow {
  agent_id: string;
  dns_enabled: number;
  cert_trusted: number;
  setup_completed: number;
  last_started_at: string | null;
  last_error: string | null;
}

function mapRow(row: AgentBridgeStateDbRow): AgentBridgeStateRow {
  return {
    agent_id: row.agent_id,
    dns_enabled: row.dns_enabled === 1,
    cert_trusted: row.cert_trusted === 1,
    setup_completed: row.setup_completed === 1,
    last_started_at: row.last_started_at,
    last_error: row.last_error,
  };
}

export function getAllAgentBridgeStates(): AgentBridgeStateRow[] {
  const db = getDbInstance();
  const rows = db
    .prepare("SELECT * FROM agent_bridge_state ORDER BY agent_id ASC")
    .all() as AgentBridgeStateDbRow[];
  return rows.map(mapRow);
}

export function getAgentBridgeState(agentId: string): AgentBridgeStateRow | null {
  const db = getDbInstance();
  const row = db.prepare("SELECT * FROM agent_bridge_state WHERE agent_id = ?").get(agentId) as
    | AgentBridgeStateDbRow
    | undefined;
  return row ? mapRow(row) : null;
}

export function upsertAgentBridgeState(
  row: Partial<AgentBridgeStateRow> & { agent_id: string }
): void {
  const db = getDbInstance();
  const existing = getAgentBridgeState(row.agent_id);

  if (!existing) {
    db.prepare(
      `INSERT INTO agent_bridge_state
         (agent_id, dns_enabled, cert_trusted, setup_completed, last_started_at, last_error)
       VALUES (?, ?, ?, ?, ?, ?)`
    ).run(
      row.agent_id,
      row.dns_enabled !== undefined ? (row.dns_enabled ? 1 : 0) : 0,
      row.cert_trusted !== undefined ? (row.cert_trusted ? 1 : 0) : 0,
      row.setup_completed !== undefined ? (row.setup_completed ? 1 : 0) : 0,
      row.last_started_at ?? null,
      row.last_error ?? null
    );
  } else {
    const fields: string[] = [];
    const values: (string | number | null)[] = [];

    if (row.dns_enabled !== undefined) {
      fields.push("dns_enabled = ?");
      values.push(row.dns_enabled ? 1 : 0);
    }
    if (row.cert_trusted !== undefined) {
      fields.push("cert_trusted = ?");
      values.push(row.cert_trusted ? 1 : 0);
    }
    if (row.setup_completed !== undefined) {
      fields.push("setup_completed = ?");
      values.push(row.setup_completed ? 1 : 0);
    }
    if (row.last_started_at !== undefined) {
      fields.push("last_started_at = ?");
      values.push(row.last_started_at);
    }
    if (row.last_error !== undefined) {
      fields.push("last_error = ?");
      values.push(row.last_error);
    }

    if (fields.length === 0) return;

    values.push(row.agent_id);
    db.prepare(`UPDATE agent_bridge_state SET ${fields.join(", ")} WHERE agent_id = ?`).run(
      ...values
    );
  }
}

export function setLastStarted(agentId: string, ts: string): void {
  const db = getDbInstance();
  db.prepare(
    `INSERT INTO agent_bridge_state (agent_id, last_started_at)
     VALUES (?, ?)
     ON CONFLICT(agent_id) DO UPDATE SET last_started_at = excluded.last_started_at`
